 14	 * NOTE: The built web UI hardcodes DAEMON_API_BASE to localhost:3456.
 15	 * When the E2E daemon runs on an ephemeral port, browser-side fetch calls
 16	 * fail. Tests that verify data values from fixtures are skipped with a note.
 17	 * Structure/interaction tests pass because they don't depend on loaded data.
 18	 */
 19	
 20	test.describe('Dashboard Overview', () => {
 21		// AC: @ui-dashboard-overview ac-1
 22		test.describe('Active Work Section', () => {
 23			test('renders active work section', async ({ page }) => {
 24				await page.goto('/');
 25				const section = page.getByTestId('active-work-section');
 26				await expect(section).toBeVisible();
 27			});
 28	
 29			test('shows no-active-work empty state when no agents running', async ({ page }) => {
 30				await page.goto('/');
 31				// In test fixture, no dispatch is running
 32				const noWork = page.getByTestId('no-active-work');
 33				await expect(noWork).toBeVisible();
 34				await expect(noWork).toContainText('No agents currently running');
 35			});
 36		});
 37	
 38		// AC: @ui-dashboard-overview ac-1
 39		test.describe('Status Summary', () => {
 40			test('displays status summary section with heading', async ({ page }) => {
 41				await page.goto('/');
 42				const section = page.getByTestId('status-summary-section');
 43				await expect(section).toBeVisible();
 44				await expect(section.locator('h2')).toContainText('Status Summary');
 45			});
 46	
 47			test('displays all 7 status count cards', async ({ page }) => {
 48				await page.goto('/');
 49	
 50				const countsContainer = page.getByTestId('dashboard-counts');
 51				await expect(countsContainer).toBeVisible();
 52	
 53				// All status types should be present with labels (not dependent on data)
 54				await expect(page.getByTestId('task-count-ready')).toBeVisible();
 55				await expect(page.getByTestId('task-count-in_progress')).toBeVisible();
 56				await expect(page.getByTestId('task-count-needs_work')).toBeVisible();
 57				await expect(page.getByTestId('task-count-pending_review')).toBeVisible();
 58				await expect(page.getByTestId('task-count-blocked')).toBeVisible();
 59				await expect(page.getByTestId('task-count-completed')).toBeVisible();
 60				await expect(page.getByTestId('task-count-cancelled')).toBeVisible();
 61			});
